set -euo pipefail; python3 - <<'PY'
import hashlib, json, os, re, shlex, subprocess
from pathlib import Path
UNIT='frankenstein-chatgpt-client.service'
props=['ActiveState','SubState','MainPID','ExecStart','FragmentPath','DropInPaths','Environment']
def show(prop):
    cp=subprocess.run(['systemctl','--user','show',UNIT,'-p',prop,'--value'],text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=False)
    return cp.stdout.strip()
raw={p:show(p) for p in props}
# Never print secrets. Keep only identity/path/config keys from Environment.
safe_keys={'FRANK_STERN','FRANK_VOICE_MACHINE_ID','FRANK_VOICE_OWNER','FRANK_VOICE_PERSON','FRANK_VOICE_DB_PATH','LOCAL_BRIDGE_MACHINE_ID','LOCAL_BRIDGE_OWNER'}
safe_env={}
try:
    for item in shlex.split(raw.get('Environment','')):
        if '=' in item:
            k,v=item.split('=',1)
            if k in safe_keys: safe_env[k]=v
except Exception as e:
    safe_env={'parse_error':type(e).__name__}
out={k:v for k,v in raw.items() if k!='Environment'}
out['safe_environment']=safe_env
pid=int(raw.get('MainPID') or 0)
if pid>0 and Path(f'/proc/{pid}').exists():
    try:
        cmd=Path(f'/proc/{pid}/cmdline').read_bytes().replace(b'\0',b' ').decode('utf-8','replace').strip()
    except Exception as e: cmd=f'<{type(e).__name__}>'
    out['proc_cmdline']=cmd
    penv={}
    try:
        for item in Path(f'/proc/{pid}/environ').read_bytes().split(b'\0'):
            if b'=' not in item: continue
            k,v=item.split(b'=',1); ks=k.decode('utf-8','replace')
            if ks in safe_keys: penv[ks]=v.decode('utf-8','replace')
    except Exception as e: penv={'parse_error':type(e).__name__}
    out['proc_safe_environment']=penv
# Find exact Python script from argv/ExecStart, hash it, inspect nearby loader.
candidates=[]
for text in [out.get('proc_cmdline',''),raw.get('ExecStart','')]:
    for m in re.findall(r'(/[^\s;{}\"\']+\.py)', text or ''):
        p=Path(m)
        if p.is_file() and p not in candidates: candidates.append(p)
out['python_scripts']=[]
for p in candidates:
    b=p.read_bytes(); src=b.decode('utf-8','replace')
    entry={'path':str(p),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)}
    for key in ('LIVE_STERN','load_live_stern','FRANK_STERN','voice_host_agent'):
        entry[key]=key in src
    out['python_scripts'].append(entry)
# Resolve the live stern path from process env first, otherwise known canonical path.
procenv=out.get('proc_safe_environment') or {}
stern_path=Path(procenv.get('FRANK_STERN') or safe_env.get('FRANK_STERN') or (Path.home()/'.claude/star/stern.py')).expanduser()
out['resolved_stern_path']=str(stern_path)
if stern_path.is_file():
    b=stern_path.read_bytes(); src=b.decode('utf-8','replace')
    out['resolved_stern_sha256']=hashlib.sha256(b).hexdigest()
    names=[]
    for pat in [r'^def (_f2wp1207[^ (]+)',r'^def (run_canonical_turn)',r'^def (zyklus_[^ (]+)',r'^def ([^ (]*grid[^ (]*)']:
        names += re.findall(pat,src,re.M|re.I)
    out['stern_relevant_definitions']=sorted(set(names))[:100]
    out['stern_has_turn_auto']='def _f2wp1207_turn_loop_auto' in src
    out['stern_has_grf_input']='grf_input' in src
print(json.dumps(out,ensure_ascii=False,indent=2,sort_keys=True))
